export type Result = { kind: 'ok'; value: number } | { kind: 'error'; reason: string };

export function parse(raw: string): Result {   // return type is the documentation
  const n = Number(raw);
  return Number.isFinite(n) ? { kind: 'ok', value: n } : { kind: 'error', reason: 'not a number' };
}
